ESTADO_ETAPA44 = "APROFUNDAMENTO_TOTAL_DA_ETAPA43"
REGRA_ETAPA44 = (
    "Nenhum item definitivo pode permanecer apenas estrutural. "
    "Cada item precisa de resposta completa, prova/desenvolvimento, aula detalhada, aula passo a passo e teste de profundidade."
)


def itens_aprofundados_etapa44() -> tuple[ProvaAprofundadaEtapa44, ...]:
    return ITENS_APROFUNDADOS_ETAPA44


def buscar_aprofundamento(id_item: str) -> ProvaAprofundadaEtapa44:
    for item in ITENS_APROFUNDADOS_ETAPA44:
        if item.id == id_item or item.id_origem == id_item:
            return item
    raise KeyError(id_item)


def relatorio_etapa44() -> dict[str, object]:
    completos = tuple(i for i in ITENS_APROFUNDADOS_ETAPA44 if i.completa())
    profundos = tuple(i for i in ITENS_APROFUNDADOS_ETAPA44 if i.profunda())
    monumentais = tuple(i for i in ITENS_APROFUNDADOS_ETAPA44 if i.nivel_honestidade == "COMPLETO_PEDAGOGICO_COM_MAPA_DE_PROVA_LONGA")
    abertos = tuple(i for i in ITENS_APROFUNDADOS_ETAPA44 if i.nivel_honestidade == "PROBLEMA_ABERTO_ENUNCIADO_E_CONTEXTO_COMPLETO")
    return {
        "etapa": 44,
        "estado": ESTADO_ETAPA44,
        "total": len(ITENS_APROFUNDADOS_ETAPA44),
        "completos": len(completos),
        "profundos": len(profundos),
        "incompletos": len(ITENS_APROFUNDADOS_ETAPA44) - len(completos),
        "nao_profundos": len(ITENS_APROFUNDADOS_ETAPA44) - len(profundos),
        "monumentais_com_mapa": len(monumentais),
        "problemas_abertos_honestos": len(abertos),
    }


def exigir_aprofundamento_total_etapa44() -> None:
    falhas = tuple(i.id for i in ITENS_APROFUNDADOS_ETAPA44 if not i.completa() or not i.profunda())
    if len(ITENS_APROFUNDADOS_ETAPA44) != 200 or falhas:
        raise AssertionError(f"Etapa 44 não aprofundada: total={len(ITENS_APROFUNDADOS_ETAPA44)}, falhas={falhas[:10]}")
